import { apiRequest } from "@/client";

// Интерфейс для подкатегории
export interface Subcategory{
    slug: string;
    name: string;
    category: Category[];
    
}

// Интерфейс для категории
export interface Category{
    name: string;
    subCategories: Subcategory[]
}

// Интерфейс для курсов
export interface CourseDetails {
  id: number;
  name: string;
  price: number;
  discount: number;
  creditMonthly: number;
  description: string;
  advantages: string;
  flaws: string;
  documentType: string;
  difficulty: string;
  duration: string;
  JobGuarantee: boolean;
  subcategory: {
    slug: string;
    name: string;
    category: {
      name: string;
      contentType: {
        type: string;
      };
    };
  };
}

// API-клиент для курсов
export const couresAPI ={
    // Получить структуру меню для аккордеона
    getMenu: async(): Promise<Category[]> =>{
        return apiRequest<Category[]>('/courses/menu');
    },
    // Получить данные конкретного курса
    getCourse: async(slug: string): Promise<CourseDetails> => {
        return apiRequest<CourseDetails>(`/courses/${slug}`);
    },
}